6	/**
7	 * Change the hub itself by talking (ash-day step 15). A Mono passes Ash's words to `startHubChange`: the app makes a
8	 * preview copy of the hub's own repo (src-tauri/src/self_build.rs) and a Claude Code worker makes the change there, one
9	 * commit per part. On its report the Mono calls `readyHubChange`: Ash gets Now | Preview, Apply and Discard (the
10	 * shared change bar). Each applied commit is its own Bot changes row, so "undo that colour" undoes only that one.
11	 * What may change is decided in Rust; a refusal comes back in plain words.
12	 */
13	export const HUB_CODE = "hub-code";
14	
15	/** How this copy puts a change in: a dev copy shows it in place, the installed app builds and ships it. */
16	export type HubDelivery = "inPlace" | "rebuild";
17	
18	export type HubCodeCommands = {
19	  prepare(id: string): Promise<{ id: string; folder: string; base: string; delivery: HubDelivery }>;
20	  collect(id: string): Promise<{ delivery: HubDelivery; commits: { sha: string; subject: string; files: string[] }[]; blocked: { path: string; area: string }[] }>;
21	  preview(id: string, on: boolean): Promise<void>;
22	  apply(id: string): Promise<{ sha: string; subject: string }[]>;
23	  discard(id: string): Promise<void>;
24	  revert(sha: string): Promise<string>;
25	  ping(): Promise<void>;
26	  live(): Promise<{ id: string; delivery: HubDelivery } | null>;
27	};
28	let commands: HubCodeCommands = {
29	  prepare: (id) => invoke("hub_change_prepare", { id }),
30	  collect: (id) => invoke("hub_change_collect", { id }),
31	  preview: (id, on) => invoke("hub_change_preview", { id, on }),
32	  apply: (id) => invoke("hub_change_apply", { id }),
33	  discard: (id) => invoke("hub_change_discard", { id }),
34	  revert: (sha) => invoke("hub_change_revert", { sha }),
35	  ping: () => invoke("hub_change_ping"),
36	  live: () => invoke("hub_change_live"),
37	};
38	export function setHubCodeCommands(next: HubCodeCommands): void {
39	  commands = next;
40	}
41	const plain = (e: unknown) => new Error(typeof e === "string" ? e : e instanceof Error ? e.message : "That didn't go through.");
42	
43	/** While a preview shows, the window says it's still there; without that, Rust takes the preview out. */
44	let pinger: ReturnType<typeof setInterval> | undefined;
45	function keepPinging(on: boolean): void {
46	  if (on && !pinger) pinger = setInterval(() => void commands.ping().catch(() => undefined), 5_000);
47	  if (!on && pinger) {
48	    clearInterval(pinger);
49	    pinger = undefined;
50	  }
51	}
52	
53	type Part = { sha: string };
54	type ChangeData = { id: string; delivery?: HubDelivery };
55	/** The installed app's preview is a browser page that outlives the window, so only an in-place one is kept alive. */
56	const watches = (data: unknown, on: boolean) => on && (data as ChangeData).delivery !== "rebuild";
57	
58	registerChangeKind(HUB_CODE, {
59	  preview: async (data, on) => {
60	    await commands.preview((data as ChangeData).id, on).catch((e) => Promise.reject(plain(e)));
61	    keepPinging(watches(data, on));
62	  },
63	  apply: async (data) => {
64	    const applied = await commands.apply((data as ChangeData).id).catch((e) => Promise.reject(plain(e)));
65	    keepPinging(false);
66	    return applied.map((c) => ({ title: c.subject || "Hub change", data: { sha: c.sha } satisfies Part }));
67	  },
68	  discard: async (data) => {
69	    await commands.discard((data as ChangeData).id).catch((e) => Promise.reject(plain(e)));
70	    keepPinging(false);
71	  },
72	  undo: (part) => commands.revert((part as Part).sha).catch((e) => Promise.reject(plain(e))),
73	  redo: async (_part, undone) => {
74	    if (typeof undone !== "string") throw new Error("Nothing to redo.");
75	    await commands.revert(undone).catch((e) => Promise.reject(plain(e)));
76	  },
77	});
