81	/** Make the preview copy. Returns its id and folder, for the worker's brief. */
82	export async function startHubChange(ask: string, title: string | undefined, by: string, now = Date.now()) {
83	  const id = `hc-${now.toString(36)}${Math.random().toString(36).slice(2, 6)}`;
84	  const change = await commands.prepare(id).catch((e) => Promise.reject(plain(e)));
85	  pending.set(id, {
86	    title: title?.trim() || ask.split("\n")[0].slice(0, 120),
87	    by,
88	    ask,
89	    delivery: change.delivery,
90	  });
91	  return { changeId: id, folder: change.folder, delivery: change.delivery };
92	}
