94	/** What the bar says for each way a change reaches the app; a dev copy's in-place preview needs no special words. */
95	function deliveryText(delivery: HubDelivery) {
96	  if (delivery !== "rebuild") return {};
97	  return {
98	    nowText: "Now: your hub as it is.",
99	    previewText: "Preview: open in your browser.",
100	    applyText: "Rebuild and ship",
101	    workingText: "Building the hub with your change, then it restarts by itself. This takes a few minutes.",
102	  };
103	}
