105	/** The brief the Claude Code worker gets: Ash's words and where to work. The limits are enforced, not asked for. */
106	export function hubChangeBrief(ask: string, folder: string): string {
107	  return [
108	    forUser`Ash asked for a change to MonoCode Hub itself: "${ask}"`,
109	    forUser`Make it in ${folder}, a preview copy of the hub's own code. The running hub doesn't change until Ash clicks Apply.`,
110	    forUser("One git commit per separate part of the ask, each subject a few plain words Ash can read (\"New chat button is at the top\")."),
111	    "Only how the app looks and works on a screen can change here: src/ and public/, but not the engine (src/integrations, src/platform, src/features/sessions/model, src/features/hub/model, src/features/agent-app), Settings, keys, the Monos list or src/main.tsx. Those need a real build and go to the MonoCode Hub lead; the app refuses them here, so say so plainly if the ask needs one.",
112	    "Use the theme tokens for colour. Run npx tsc --noEmit and the tests of what you touched, then report each commit in one line.",
113	  ].join("\n");
114	}
