116	/** The worker is done: show Ash Now | Preview. A change that touches the protected core is thrown away, said plainly. */
117	export async function readyHubChange(changeId: string, by: string) {
118	  if (!/^hc-[a-z0-9]+$/.test(changeId)) throw new Error("No hub change with that id. Start one with hub_change {ask}.");
119	  const known = pending.get(changeId) ?? offeredChanges().find((o) => o.id === changeId) ?? { title: "Your hub change", by };
120	  const got = await commands.collect(changeId).catch((e) => Promise.reject(plain(e)));
121	  if (got.blocked.length) {
122	    await commands.discard(changeId).catch(() => undefined);
123	    pending.delete(changeId);
124	    const areas = [...new Set(got.blocked.map((b) => b.area))].join(", ");
125	    throw new Error(forUser`That change touches ${areas}, which has to be built and checked before it lands, so it can't go in here. It was thrown away and nothing changed. Tell Ash in those words: it goes to the MonoCode Hub lead.`);
126	  }
