44	const ALLOWED_ROOTS: [&str; 2] = ["src/", "public/"];
45	const PROTECTED: [(&str, &str); 13] = [
46	    ("src/features/settings/", "Settings"),
47	    ("src/features/providers/", "keys and providers"),
48	    ("src/features/connections/", "keys and sign-ins"),
49	    ("src/features/monos/model/", "the Monos list"),
50	    ("src/features/hubChange/", "the way changes are made"),
51	    ("src/features/selfBuild/", "the way changes are made"),
52	    ("src/features/hub/model/botChanges.ts", "Bot changes"),
53	    ("src/main.tsx", "how the app starts"),
54	    // The engine: how it works rather than how it looks. These go the Lead's way, where they're built and checked.
55	    ("src/integrations/", "the app's engine"),
56	    ("src/platform/", "the app's engine"),
57	    ("src/features/agent-app/", "the app's own tools"),
