62	/// Why a path can't be changed, or None when it may.
63	pub fn protected_area(path: &str) -> Option<&'static str> {
64	    let lower = path.to_ascii_lowercase();
65	    if [
66	        "keychain",
67	        "secret",
68	        "credential",
69	        "apikey",
70	        "api-key",
71	        "api_key",
72	    ]
73	    .iter()
74	    .any(|word| lower.contains(word))
75	    {
76	        return Some("keys and sign-ins");
77	    }
78	    if let Some((_, area)) = PROTECTED
79	        .iter()
80	        .find(|(prefix, _)| path.starts_with(prefix))
81	    {
82	        return Some(area);
83	    }
84	    if !ALLOWED_ROOTS.iter().any(|root| path.starts_with(root)) {
85	        return Some("the app's engine and build");
86	    }
87	    None
88	}
