51	  // Its red Needs you rows come from the one list the rail counts (needsYouRows.ts): its job rows, made by the same
52	  // function (with r30h's app workers no job stands for), and any worker only Ash can sort that no row carries.
53	  const needsYou = useNeedsYouRows();
54	  const loneRed = needsYou.flatMap((r) => (r.worker && r.projectId === projectId ? [r.worker] : []));
55	  // r74 (blind s06): a Lead that stopped to ask Ash before starting any job made this page say "Nobody's working on
56	  // Tally" while Today showed the ask. The chats of this project waiting on Ash are listed here too, the same red row.
57	  useWaitingChatsVersion();
58	  const waiting = waitingChats(projectId);
59	  const liveWorkers = live
60	    ? [
61	        ...beingBuiltJobRows(projectId, data.listJobs?.(projectId) ?? [], delegations, now, leadFailureOf, APP_WORKER_WHERE),
62	        ...prWatchWorkers(prWatches?.all() ?? [], projectId, now),
