337	    // Its Lead's last turn failed: the job can't move until that is dealt with. Only Ash can fix it (credits, sign-in):
338	    // Needs you; it should come right by itself: Can't answer (r27b).
339	    const failure = failureOf(j);
340	    if (failure) return failureChip(failure.tone);
341	    const stuck = stuckNow.length ? stuckForJob(j.sourceRef, delegations, now) : undefined;
342	    if (!stuck || j.state === "lead_gave_up") return jobWord(j, lead);
343	    // One of this app's workers stalled or failed under it: by the red rule, as Being built says it (r30c): red Needs you
344	    // when only Ash can sort it (credits, a rejected key, a refusal, out of retries), else grey Retrying or With <Lead>.
345	    return stuck.kind === "asking" && !stuck.escalated ? "Waiting" : stuckWorkerChip(stuck, lead);
346	  };
