349	    (data.listJobs?.(p.id) ?? []).flatMap((g) => g.jobs.filter((j) => ACTIVE_JOBS.has(j.state) && !j.parentId && !(j.state === "working" && jobRowsFinishedAt(j.sourceRef, delegations) !== undefined)).map((j) => ({ p, j, lead: g.leadName }))),
