353	  const covered = new Set(rows.flatMap(({ j }) => (stuckNow.length ? [stuckForJob(j.sourceRef, delegations, now)?.key ?? ""] : [])).filter(Boolean));
354	  if (!rows.length) return <StuckToday projectId={projectId} tone="grey" skip={covered} heading={title} />;
