173	  query: string,
174	  limit = MAX_NOTE_PICKER,
175	): RankedFile[] {
176	  const needle = query.replace(/\/+$/, "").trim().toLowerCase();
177	  if (!needle) {
178	    return [...notes]
179	      .sort((a, b) => b.updatedAt - a.updatedAt)
180	      .slice(0, limit)
181	      .map((note) => ({
182	        ...notesAsProjectFiles([note])[0]!,
183	        score: 0,
184	        positions: [],
185	      }));
186	  }
187	
188	  const scored: { note: Note; score: number; positions: number[] }[] = [];
189	  for (const note of notes) {
190	    const titleHit = fuzzyMatch(needle, note.title);
191	    const slugHit = titleHit ? null : fuzzyMatch(needle, note.slug);
192	    const tagHit =
193	      titleHit || slugHit
194	        ? null
195	        : note.tags
196	            .map((tag) => fuzzyMatch(needle.replace(/^#/, ""), tag))
197	            .find(Boolean);
198	    const hit = titleHit ?? slugHit ?? tagHit;
199	    if (!hit) continue;
200	    scored.push({
201	      note,
202	      score: titleHit ? hit.score + 400 : tagHit ? hit.score + 200 : hit.score,
203	      positions: titleHit ? hit.positions : [],
204	    });
205	  }
206	  scored.sort((a, b) => {
207	    if (b.score !== a.score) return b.score - a.score;
208	    return b.note.updatedAt - a.note.updatedAt;
209	  });
210	  return scored.slice(0, limit).map((row) => ({
211	    ...notesAsProjectFiles([row.note])[0]!,
212	    score: row.score,
213	    positions: row.positions,
214	  }));
215	}
