218	export function noteTitle(text: string): string {
219	  const heading = text.match(/^\s{0,3}#{1,6}\s+(.+)$/m);
220	  if (heading) {
221	    const title = unwrapMarkdown(heading[1]).slice(0, MAX_TITLE);
222	    if (title) return title;
