224	  let inFence = false;
225	  for (const line of text.split(/\r?\n/)) {
226	    if (/^\s*```/.test(line)) {
227	      inFence = !inFence;
228	      continue;
229	    }
230	    if (inFence) continue;
231	    const trimmed = line.trim();
232	    if (!trimmed || trimmed === "---") continue;
233	    const title = unwrapMarkdown(trimmed).slice(0, MAX_TITLE);
234	    if (title) return title;
235	  }
236	  return "Untitled";
