106	/**
107	 * Reminders always lead, followed by folders, pins, and loose sessions.
108	 * Reminder membership only changes this view, preserving saved folders/pins.
109	 */
110	export function buildSessionList(
111	  visible: SessionSummary[],
112	  folders: SessionFolder[],
113	  ungrouped: SessionSummary[],
114	  pinnedCollapsed = false,
115	  reminderGroup?: { sessionIds: readonly string[]; collapsed: boolean },
116	): SessionListEntry[] {
117	  const byId = new Map(visible.map((session) => [session.id, session]));
118	  const reminderIds = new Set(reminderGroup?.sessionIds);
119	  const entries: SessionListEntry[] = [];
120	  const reminderSessions = [...reminderIds].flatMap((id) => {
121	    const session = byId.get(id);
122	    return session ? [session] : [];
123	  });
124	  if (reminderSessions.length) {
125	    entries.push({
126	      kind: "reminders",
127	      collapsed: reminderGroup?.collapsed ?? false,
128	      sessions: reminderSessions,
129	    });
130	  }
131	  for (const folder of folders) {
132	    const members: SessionSummary[] = [];
133	    for (const id of folder.sessionIds) {
134	      const session = byId.get(id);
135	      if (session && !reminderIds.has(id)) members.push(session);
136	    }
137	    if (members.length === 0) continue;
138	    members.sort(compareSessionSummaries);
139	    entries.push({ kind: "folder", folder, sessions: members });
140	  }
141	
142	  const remaining = ungrouped.filter((session) => !reminderIds.has(session.id));
143	  const pinned = remaining.filter((session) => session.pinned);
144	  if (pinned.length > 0) {
145	    entries.push({
146	      kind: "pinned",
147	      collapsed: pinnedCollapsed,
148	      sessions: pinned,
149	    });
150	  }
151	  for (const session of remaining) {
152	    if (!session.pinned) entries.push({ kind: "session", session });
153	  }
154	  return entries;
155	}
