157	export function sessionListNavigationIds(
158	  entries: readonly SessionListEntry[],
159	  expandCollapsed: boolean,
160	): string[] {
161	  const ids: string[] = [];
162	  for (const entry of entries) {
163	    if (entry.kind === "session") {
164	      ids.push(entry.session.id);
165	      continue;
166	    }
167	    if (entry.kind === "pinned" || entry.kind === "reminders") {
168	      if (!entry.collapsed || expandCollapsed) {
169	        ids.push(...entry.sessions.map((session) => session.id));
170	      }
171	      continue;
172	    }
173	    if (entry.kind !== "folder") continue;
174	    if (entry.folder.collapsed && !expandCollapsed) continue;
175	    ids.push(...entry.sessions.map((session) => session.id));
176	  }
177	  return ids;
178	}
