180	export function createFolderWithSessions(
181	  folders: SessionFolder[],
182	  sessionIds: string[],
183	  name?: string,
184	): { folders: SessionFolder[]; id: string } {
185	  const ids = uniqueIds(sessionIds);
186	  if (ids.length === 0) return { folders, id: "" };
187	  const next = removeSessions(folders, ids);
188	  const id = crypto.randomUUID();
189	  const folder: SessionFolder = {
190	    id,
191	    name: name ?? uniqueFolderName(next),
192	    sessionIds: ids,
193	    collapsed: false,
194	  };
